mapper.select:
SELECT COUNT(*)                                        AS sample_count,
       AVG(CAST(e.amount AS DOUBLE) / t.original_price) AS avg_ratio
FROM escrow e
         JOIN listing l ON l.id = e.listing_id
         JOIN ticket t ON t.id = l.ticket_id
WHERE e.status = 'CONFIRMED'
  AND e.confirmed_at >= #{since}
  AND t.category = #{category}
  AND t.original_price > 0
  AND TIMESTAMPDIFF(HOUR, e.paid_at, t.expires_at) >= #{minHours}
  AND TIMESTAMPDIFF(HOUR, e.paid_at, t.expires_at) < #{maxHours}
